import { Catalog, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: View . This represents a single page of product impressions and one Catalog event should be sent for each item on the page. Subtypes:    **View Recommendations:** If provided a recommendation ID then the product impression was provided by a recommendation   **View Search Results:** If provided a search result ID then the product impression was provided by a search result. This includes category product listings. 
*/
export type ViewProductImpressions = {
    events: Array<Catalog | Identity | PartyIdentification | ErrorEvent>;
}

export class ViewProductImpressionsBuilder {

    private viewProductImpressions: ViewProductImpressions = {
        events: []
    }

    private catalog!: Catalog;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCatalog(catalog: Catalog) : ViewProductImpressionsBuilder {
        this.catalog = catalog;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : ViewProductImpressionsBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : ViewProductImpressionsBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : ViewProductImpressionsBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : ViewProductImpressions {
        if(this.catalog) {
            this.viewProductImpressions.events.push(this.catalog);
        }
        if(this.errorEvent) {
            this.viewProductImpressions.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.viewProductImpressions.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.viewProductImpressions.events.push(this.partyIdentification);
        }

        return this.viewProductImpressions;
    }
}
